from collections.abc import MutableMapping
import math
import time

def check_rate_limit(buckets: MutableMapping[str, dict[str, float]], key: str, capacity: float=10.0, refill_rate: float=1.0, cost: float=1.0, now: float | None=None) -> tuple[bool, float]:
    if capacity <= 0 or refill_rate <= 0 or cost <= 0:
        raise ValueError('capacity, refill_rate and cost must be positive')
    if cost > capacity:
        raise ValueError('cost can never be satisfied: it exceeds capacity')
    now = time.monotonic() if now is None else now
    bucket = buckets.get(key)
    if bucket is None:
        bucket = buckets[key] = {'tokens': float(capacity), 'last': now}
    elapsed = max(0.0, now - bucket['last'])
    bucket['tokens'] = min(float(capacity), bucket['tokens'] + elapsed * refill_rate)
    bucket['last'] = now
    if bucket['tokens'] >= cost:
        bucket['tokens'] -= cost
        return (True, 0.0)
    return (False, (cost - bucket['tokens']) / refill_rate)

_BUCKETS: dict[str, dict[str, float]] = {}

def rate_limit_response(client_ip: str, capacity: float=20.0, refill_rate: float=5.0, buckets: MutableMapping[str, dict[str, float]] | None=None) -> tuple[int, dict[str, str], dict[str, str]] | None:
    # Returns None if the request is allowed; otherwise (status, headers, body) for a 429.
    # Call at the top of each request handler / middleware with the client's IP (or API key).
    store = _BUCKETS if buckets is None else buckets
    allowed, retry_after = check_rate_limit(store, client_ip, capacity=capacity, refill_rate=refill_rate)
    if allowed:
        return None
    seconds = max(1, math.ceil(retry_after))
    return 429, {'Retry-After': str(seconds)}, {'error': 'Too Many Requests', 'retry_after': str(seconds)}

